#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNativeClient: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = NativeClient

    public static func lift(_ handle: UInt64) throws -> NativeClient {
        return NativeClient(unsafeFromHandle: handle)
    }

    public static func lower(_ value: NativeClient) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> NativeClient {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: NativeClient, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNativeClient_lift(_ handle: UInt64) throws -> NativeClient {
    return try FfiConverterTypeNativeClient.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNativeClient_lower(_ value: NativeClient) -> UInt64 {
    return FfiConverterTypeNativeClient.lower(value)
}






public protocol NativeEnrollmentClientProtocol: AnyObject, Sendable {
    
    func acceptVaultRequestCreated(json: String) throws 
    
    func approvePhoneInvitationRequest(statusJson: String, passphrase: String) throws  -> String
    
    func beginVaultRequest(origin: String, inviteToken: String, displayName: String) throws  -> String
    
    /**
     * Abandons a local claimant flow; it does not perform a server-side cancellation.
     */
    func cancelPhoneFlow() throws 
    
    func checkpoint() throws  -> Data
    
    func claimPhoneInvitationRequest(qrJson: String) throws  -> String
    
    func clearVaultRequest() throws 
    
